{"h": "التقديم", "src": "hawramani", "dict": "دستور العلماء للأحمدنكري", "def": "التَّقْدِيم: مصدر مُتَعَدٍّ وَهُوَ نقل الشَّيْء من مَكَانَهُ إِلَى مَا قبله فَإِن قلت إِنَّهُم يَقُولُونَ إِن تَقْدِيم الْمسند إِلَيْهِ على الْخَبَر يكون لوجوه. إِمَّا لكَون ذكره أهم وَإِمَّا لكَونه أ", "id": 816245}
{"h": "العرض", "src": "hawramani", "dict": "معجم مقاليد العلوم للسيوطي", "def": "العَرَض: مَا يتبع الْمَرَض.", "id": 807202, "root": "عرض"}
{"h": "العرض", "src": "hawramani", "dict": "معجم مقاليد العلوم للسيوطي", "def": "العَرَضُ: مُمكن يكون فِي مَوْضُوع.", "id": 807200, "root": "عرض"}
{"h": "العرض", "src": "hawramani", "dict": "معجم مقاليد العلوم للسيوطي", "def": "العَرَضُ: هُوَ الْحَال فِي المتحيز.", "id": 807201, "root": "عرض"}
{"h": "العرض", "src": "hawramani", "dict": "معجم مقاليد العلوم للسيوطي", "def": "العَرْضُ: أَخذ الحَدِيث المقروء - هُوَ أَو غَيره - على الشَّيْخ كِتَابَة أَو حفظا.", "id": 807199, "root": "عرض"}
{"h": "العرض", "src": "hawramani", "dict": "التوقيف على مهمات التعاريف للمناوي", "def": "العرض: بالتحريك، الموجود الذي يحتاج في وجوده إلى موضع أي محل يقوم به كاللون المحتاج في وجوده إلى جسم يحله ويقوم هو به.", "id": 814431, "root": "عرض"}
{"h": "العرض", "src": "hawramani", "dict": "التوقيف على مهمات التعاريف للمناوي", "def": "العرض: بالسكون: خلاف الطول، وأصله أن يقال في الأجسام، ثم استعمل في غيرها. والعارض: البادي عرضه، فتارة يختص بالسحاب نحو {هَذَا عَارِضٌ مُمْطِرُنَا} ، وتارة بما يعرض من السقم فيقال: به عارض من سقم، وتار", "id": 814432, "root": "عرض"}
{"h": "العرض", "src": "hawramani", "dict": "دستور العلماء للأحمدنكري", "def": "الْعرض: بِكَسْر الأول وَسُكُون الثَّانِي (آبرو وعزت وَحرمت) وبفتح الْعين وَسُكُون الثَّانِي فِي اللُّغَة الْإِظْهَار والكشف. وَمِنْه قَول الْفُقَهَاء وَلَا تعرض الْأمة إِذا بلغت فِي إِزَار وَاحِد أَي ", "id": 817065, "root": "عرض"}
{"h": "العرض", "src": "hawramani", "dict": "كشّاف اصطلاحات الفنون والعلوم للتهانوي", "def": "العرض:[في الانكليزية] Goods ،extent ،wideness ،offer Iatitude [ في الفرنسية] Marchandise ،ampleur ،largeur ،offre ،latitude بالفتح وسكون الراء في اللغة المتاع وهو الذي لا يدخله كيل ولا وزن ولا يكون حي", "id": 820193, "root": "عرض"}
{"h": "العرض", "src": "hawramani", "dict": "كشّاف اصطلاحات الفنون والعلوم للتهانوي", "def": "العرض:[في الانكليزية] Accident [ في الفرنسية] Accident بفتحتين عند المتكلّمين والحكماء وغيرهم هو ما يقابل الجوهر كما عرفت. ويطلق أيضا على الكلّي المحمول على الشيء الخارج عنه ويسمّى عرضيا أيضا، ويقابله", "id": 820194, "root": "عرض"}
{"h": "العرض", "src": "hawramani", "dict": "معجم البلدان لياقوت الحموي", "def": "العَرْضُ:\nبالفتح ثم السكون، وآخره ضاد معجمة، خلاف الطول: جبل مطلّ على بلد فاس بالمغرب.", "id": 968954, "root": "عرض"}
{"h": "العرض", "src": "hawramani", "dict": "معجم البلدان لياقوت الحموي", "def": "العِرْضُ:\nبكسر أوله، وسكون ثانيه، وآخره ضاد معجمة، قال الأزهري: العرض وادي اليمامة، ويقال لكل واد فيه قرى ومياه عرض، وقال الأصمعي: أخصب ذلك العرض وأخصبت أعراض المدينة وهي قراها التي في أوديتها، وقال ش", "id": 968953, "root": "عرض"}
{"h": "العرض", "src": "hawramani", "dict": "التعريفات الفقهيّة للبركتي", "def": "العَرض: بالفتح الموجودُ الذي يحتاج في وجوده إلى موضع، وأيضاً: المتاعُ وراجع العروض، وبالكسر هو موضعُ المدح والذم من الإنسان، سواء كان في نفسه أو سلفه أو من يلزمه أمْرُه.", "id": 835178, "root": "عرض"}
{"h": "العرض", "src": "hawramani", "dict": "المعجم الوسيط لمجموعة من المؤلفين", "def": "(الْعرض) الْمَتَاع وكل شَيْء سوى الدَّرَاهِم وَالدَّنَانِير يُقَال أخذت فِي هَذِه السّلْعَة عرضا أَعْطَيْت فِي مقابلها سلْعَة أُخْرَى وَخلاف الطول والجبل والجيش الْعَظِيم وَعرض الْحَال طلب مَكْتُوب يق", "id": 877888, "root": "عرض"}
{"h": "العرض", "src": "hawramani", "dict": "مختصر العبارات لمعجم مصطلحات القراءات للدوسري", "def": "الَعرْض:تلاوة القرآن على الشيخ، وهو أحد أنواع طرق التحمل والأخذ عن المشايخ.", "id": 912840, "root": "عرض"}
{"h": "العرض", "src": "ocr", "dict": "المعجم الوسيط", "def": "ما يطرأ ويزول من مرض ونحوه متاع الدنيا قلَّ أو كثر (فى علم المنطق): ما قام بغيره, \"ضد الجوهر\", كالبياض والطول والقصر (في الطب): ما يحسُّه المريض من الظواهر الدَّالة على المرض", "trans": "", "id": 18599, "root": "عرض"}
{"h": "العرض", "src": "ocr", "dict": "المعجم الوسيط", "def": "يقال: نظر إليه عن عُرُضٍ: من جانب", "trans": "", "id": 18598, "root": "عرض"}
{"h": "العرض", "src": "ocr", "dict": "المعجم الوسيط", "def": "المتاعُ كلُّ شيءٍ سوى الدراهم والدنانير خلاف الطُّول الجبل الجيش العظيم", "trans": "", "id": 18594, "root": "عرض"}
{"h": "العرض", "src": "ocr", "dict": "المعجم الوسيط", "def": "عُرْض الشيء: جانبه وناحيته؛ يقال: عُرْضُ الجبل: سفحه, وعُرْض السيف: صفحُه, وعُرْضُ العُنُق والوجْه: جانبه وسطُه؛ يقال: عُرْض البحر والنهر: وسطُه عُرض الحديث: مُعظَمُه عُرض الناس: معظمهم هو من عُرْض النَّاس: من عامَّتِهم ناقةٌ عُرْضُ أسفار: قوية على السَّفر", "trans": "", "id": 18597, "root": "عرض"}
{"h": "العرض", "src": "ocr", "dict": "المعجم الوسيط", "def": "البدَنُ النفس ما يُمْدَحُ ويُذَمُّ من الإنسان, سواء كان فى نفسه, أو سلفه, أو من يلزمه أمره الحسَب الرائحة أيًّا كانت السحابُ العظيم الوادى فيه الشجر", "trans": "", "id": 18596, "root": "عرض"}
{"h": "المشاهدة", "src": "hawramani", "dict": "معجم مقاليد العلوم للسيوطي", "def": "المشاهَدَةُ: إِدْرَاك الجزئي حَاضرا فِي الْخَارِج.\nالمشَاهدة الحقيقيةُ: إِدْرَاك عين الْحَاضِر فِي الْخَارِج.", "id": 807565}
{"h": "المشاهدة", "src": "hawramani", "dict": "معجم مقاليد العلوم للسيوطي", "def": "المُشَاهَدةُ: وجود الْحق من غير بَقَاء تُهْمَة.اللوائحُ: أَمَارَات طُلُوع شموس المعارف يكون زَوَالهَا بِسُرْعَة.", "id": 807566}
{"h": "المشاهدة", "src": "hawramani", "dict": "التوقيف على مهمات التعاريف للمناوي", "def": "المشاهدة: تطلق على رؤية الأشياء بدلائل التوحيد، وتطلق بإزاء حقيقة اليقين من غير شك، وتطلق بإزاء رؤية الحق في الأشياء، وذلك هو الوجه الذي له تعالى بحسب ظاهريته في كل شيء. وعرفها بعضهم بأنها وجود الحق م", "id": 815033}
{"h": "المشاهدة", "src": "hawramani", "dict": "كشّاف اصطلاحات الفنون والعلوم للتهانوي", "def": "المشاهدة:[في الانكليزية] Witnessing ،seeing [ في الفرنسية] Vue ،vision هي الإدراك بإحدى الحواس الظاهرة أو الباطنة. والمشاهدات هي المحسوسات، وقد تجعل أعمّ أو أخصّ منها وقد سبق. وشارح التجريد أطلق المشا", "id": 820773}
{"h": "المشاهدة", "src": "hawramani", "dict": "المعجم الوسيط لمجموعة من المؤلفين", "def": "(الْمُشَاهدَة) الْإِدْرَاك بِإِحْدَى الْحَواس", "id": 883268}
{"h": "المشاهدة", "src": "ocr", "dict": "المعجم الوسيط", "def": "الإدراك بإحدى الحواس", "id": 15497}
{"h": "المشاهدة", "src": "ocr", "dict": "المعجم الكبير", "def": "الإدراكُ بإحدى الحواسِّ المُعايَنَةُ (فى الفلسفة) (Contemplation (E: رُؤْيَةٌ عَمِيقَةٌ شاملةٌ لموضع الفِكْرِ إلى حَدِّ نسيانِ الذاتِ والأشياءِ الأخرى (عند الصوفيَّة): منزِلَةٌ عاليةٌ من منازلِ السَّا", "id": 53628}
{"h": "عرض", "src": "hawramani", "dict": "لسان العرب لابن منظور", "def": "عرض: العَرْضُ: خلافُ الطُّول، والجمع أَعراضٌ؛ عن ابن الأَعرابي؛\nوأَنشد:\nيَطْوُونَ أَعْراضَ الفِجاجِ الغُبْرِ،\nطَيَّ أَخي التَّجْرِ بُرودَ التَّجْرِ\nوفي الكثير عُرُوضٌ وعِراضٌ؛ قال أََبو ذؤيب يصف برذون", "id": 772166, "root": "عرض"}
{"h": "عرض", "src": "hawramani", "dict": "المجموع المغيث في غريبي القرآن والحديث لأبو موسى المديني", "def": "(عرض) - في الحديث: \"أنّه بَعَث بَدنَةً مع رجل فقال: إن عُرِضَ لها، فانْحَرْها\" يعنى إن عُرِض لها بكَسْر أو مَرَض، والعَارِضُ: المَرِيضَة التي أصابها كَسْر، والعَرَض: ما يَعرِض من مَرضٍ ونحوِه.- في حدي", "id": 777535, "root": "عرض"}
{"h": "عرض", "src": "hawramani", "dict": "النهاية في غريب الحديث والأثر لأبي السعادات ابن الأثير الجزري", "def": "(عَرِضَ)(هـ) فِيهِ «كُلُّ المُسْلم عَلَى المُسْلم حَرَام، دَمُه ومَالُه وعِرْضُه» العِرْض. موضعُ المدْح والذَّم مِنَ الإنْسان، سَوَاءً كَانَ فِي نَفْسه أَوْ فِي سَلَفه، أَوْ مَن يَلْزمه أمْرُه.وَقِيلَ", "id": 781051, "root": "عرض"}
{"h": "عرض", "src": "hawramani", "dict": "المغرب في ترتيب المعرب للمُطَرِّزي", "def": "(ع ر ض) : (الْعَرْضُ) خِلَافُ الطُّولِ وَشَيْءٌ عَرِيضٌ (وَيُقَالُ) إنَّهُ لَعَرِيضُ الْقَفَا أَيْ أَحْمَقُ (وَلَقَدْ أَعْرَضْتُ الْمَسْأَلَةَ) جِئْتُ بِهَا عَرِيضَةً وَاسِعَةً (وَالْمِعْرَاضُ) السَّه", "id": 784287, "root": "عرض"}
{"h": "عرض", "src": "hawramani", "dict": "الشوارد للصغاني", "def": "(عرض) : المُعَرِّضُ: الذي يَخْتُنُ الصَّبيَّ.", "id": 786043, "root": "عرض"}
{"h": "عرض", "src": "hawramani", "dict": "مختار الصحاح للرازي", "def": "ع ر ض: (عَرَضَ) لَهُ كَذَا أَيْ ظَهَرَ. وَ (عَرَضْتُهُ) لَهُ أَظْهَرْتُهُ لَهُ وَأَبْرَزْتُهُ إِلَيْهِ. يُقَالُ: (عَرَضْتُ) لَهُ ثَوْبًا مَكَانَ حَقِّهِ وَثَوْبًا مِنْ حَقِّهِ بِمَعْنًى وَاحِدٍ. وَ (ع", "id": 788503, "root": "عرض"}
{"h": "عرض", "src": "hawramani", "dict": "تحفة الأريب بما في القرآن من الغريب لأبي حيان الغرناطي الأندلسي", "def": "عرض: {عرض الدنيا}: طمع. {عرضة}: نصبا، وقيل: عدة. {عرضها}: سعتها. {عرضتم}: أومأتم. {وعرضنا جهنم}: أظهرنا. {عارض}: سحاب.", "id": 790878, "root": "عرض"}
{"h": "عرض", "src": "hawramani", "dict": "المصباح المنير للفيّومي", "def": "ع ر ض : عَرُضَ الشَّيْءُ بِالضَّمِّ عِرَضًا وِزَانُ عِنَبٍ وَعَرَاضَةٌ بِالْفَتْحِ اتَّسَعَ عَرْضُهُ وَهُوَ تَبَاعُدُ حَاشِيَتَيْهِ فَهُوَ عَرِيضٌ وَالْجَمْعُ عِرَاضٌ مِثْلُ كَرِيمٍ وَكِرَامٍ فَالْعَر", "id": 793048, "root": "عرض"}
{"h": "عرض", "src": "hawramani", "dict": "كتاب التعريفات للشريف الجرجاني", "def": "العرض: الموجود الذي يحتاج في وجوده إلى موضع، أي محل، يقوم به، كاللون المحتاج في وجوده إلى جسم يحله ويقوم به، والأعراض على نوعين: قار الذات، وهو الذي يجتمع أجزاؤه في الوجود، كالبياض والسواد، وغير قار ا", "id": 795255, "root": "عرض"}
{"h": "عرض", "src": "hawramani", "dict": "مجمع بحار الأنوار للفَتِّنيّ", "def": "[عرض] نه: فيه: كل المسلم على المسلم حرام دمه وماله و\"عرضه\"، هو موضع المدح والذم من الإنسان سواء كان في نفسه أو سلفه أو من يلزمهأمره، وقيل: هو جانبه الذي يصونه من نفسه وحسبه ويحامي عنه أن ينتقص ويثلب، ", "id": 810651, "root": "عرض"}
{"h": "عرض", "src": "hawramani", "dict": "تاج العروس لمرتضى الزبيدي", "def": "عرضالعَرُوضُ، كصَبُورٍ: مَكَّةُ والمَدِينَةُ، شَرَّفَهُمَا اللهُ تَعالَى وَمَا حَوْلَهما، كَمَا فِي الصّحاح، والعُباب، والمُحْكَم، والتَّهْذِيب، مُؤَنَّثٌ، كَمَا صَرَّح بِهِ ابْن سِيدَهْ ورُوِيَ عَن م", "id": 828740, "root": "عرض"}
{"h": "عرض", "src": "hawramani", "dict": "المفردات في غريب القرآن للراغب الأصفهاني", "def": "عرضالعَرْضُ: خلافُ الطّولِ، وأصله أن يقال في الأجسام، ثمّ يستعمل في غيرها كما قال:فَذُو دُعاءٍ عَرِيضٍ[فصلت/ 51] .والعُرْضُ خصّ بالجانب، وأَعْرَضَ الشيءُ: بدا عُرْضُهُ، وعَرَضْتُ العودَ على الإناء، وا", "id": 840722, "root": "عرض"}
{"h": "عرض", "src": "hawramani", "dict": "تكملة المعاجم العربية لرينهارت دوزي", "def": "عرض: عرض نَفْسَه على فلان: عرّفه بنفسه.\nوحضر أمامه وقدّم نفسه إليه. ففي النويري (الأندلس ص480) وأعلن سليمان نفسه خليفة عند البربر وسار معهم إلى وادي القصارة الذي استولوا عليه وعرضوا أنفسهم على واضح ال", "id": 846430, "root": "عرض"}
